package net.civeira.phylax.feature.observe.observedalertrule.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class CooldownMinutesVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property cooldown minutes of observed alert rule ")
  void test_cooldown_minutes_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> CooldownMinutesVO.tryFrom(null));
    Assertions.assertEquals(1, CooldownMinutesVO.from(1).getCooldownMinutes());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> CooldownMinutesVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", CooldownMinutesVO.from(1).toString());
  }
}
